import java.util.*;

public class Test {
    int r, c;
    Scanner sca = new Scanner(System.in);
    long[][] C = new long[64][64];
    long best = Long.MAX_VALUE;
    int[] cntA = new int[64], cntB = new int[64];
    Map<Long, Long> cache = new TreeMap<>();
    char[] cs;

    private static class Frame {
        long x, y;
        int v1, v2;
        int stage;
        long acc;
        char ch;
        Frame(long x, long y, int v1, int v2) {
            this.x = x;
            this.y = y;
            this.v1 = v1;
            this.v2 = v2;
        }
    }

    void dfs(long x, long y, int v1, int v2) {
        long d = Math.abs(x - y);
        if (best <= 1 || d - C[v1][r] * C[v2][r] >= best) return;
        if (v1 == r - 1 && v2 == r - 1) {
            if (d < best) best = d;
            return;
        }
        if (v1 >= r) {
            long c1 = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
            dfs(x, y + c1 * s2, v1 - 1, v2);
        }
        if (v2 >= r) {
            long s1 = C[v1][r], c2 = C[v2][r] - C[v2 - 1][r];
            dfs(x + s1 * c2, y, v1, v2 - 1);
        }
    }

    long solve(long x0, long y0, int v10, int v20) {
        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame(x0, y0, v10, v20));
        while (!stack.isEmpty()) {
            Frame f = stack.peek();
            long k = f.x * 10000 + f.v1 * 100 + f.v2;

            if (f.stage == 0) {
                Long cached = cache.get(k);
                if (cached != null) {
                    stack.pop();
                    if (stack.isEmpty()) return cached;
                    stack.peek().acc += cached;
                    continue;
                }

                long d = Math.abs(f.x - f.y);
                if (d - C[f.v1][r] * C[f.v2][r] > best) {
                    cache.put(k, 0L);
                    stack.pop();
                    if (stack.isEmpty()) return 0L;
                    stack.peek().acc += 0L;
                    continue;
                }

                if (f.v1 < r || f.v2 < r) {
                    int sum = f.v1 + f.v2;
                    long val;
                    if (f.v1 >= cntA[sum] && f.v2 >= cntB[sum]) {
                        int nv1 = f.v1 - cntA[sum];
                        int nv2 = f.v2 - cntB[sum];
                        val = C[nv1 + nv2][nv1];
                    } else {
                        val = 0L;
                    }
                    cache.put(k, val);
                    stack.pop();
                    if (stack.isEmpty()) return val;
                    stack.peek().acc += val;
                    continue;
                }

                f.ch = cs[f.v1 + f.v2 - 1];
                f.stage = 1;
                if (f.ch != 'B') {
                    long c1 = C[f.v1][r] - C[f.v1 - 1][r];
                    long s2 = C[f.v2][r];
                    stack.push(new Frame(f.x, f.y + c1 * s2, f.v1 - 1, f.v2));
                }
                continue;
            } else if (f.stage == 1) {
                if (f.ch != 'A') {
                    long s1 = C[f.v1][r];
                    long c2 = C[f.v2][r] - C[f.v2 - 1][r];
                    f.stage = 2;
                    stack.push(new Frame(f.x + s1 * c2, f.y, f.v1, f.v2 - 1));
                } else {
                    stack.pop();
                    long val = f.acc;
                    cache.put(k, val);
                    if (stack.isEmpty()) return val;
                    stack.peek().acc += val;
                }
                continue;
            } else {
                stack.pop();
                long val = f.acc;
                cache.put(k, val);
                if (stack.isEmpty()) return val;
                stack.peek().acc += val;
            }
        }
        return 0L;
    }

    void start() {
        r = sca.nextInt(); c = sca.nextInt(); sca.nextLine();
        cs = sca.nextLine().toCharArray();
        int n = 2 * (r + c);
        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= n; j++) {
                if (j == 0) C[i][j] = 1;
                else if (i == 0) C[i][j] = 0;
                else C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        int v1 = r + c, v2 = r + c;
        long x = 0, y = 0;
        while (v1 >= r && v2 >= r) {
            if (x > y) {
                long c1 = C[v1][r] - C[v1 - 1][r], s2 = C[v2][r];
                y += c1 * s2;
                v1--;
            } else {
                long s1 = C[v1][r], c2 = C[v2][r] - C[v2 - 1][r];
                x += s1 * c2;
                v2--;
            }
        }
        best = Math.abs(x - y);
        dfs(0, 0, r + c, r + c);
        for (int i = 0; i < n; i++) {
            cntA[i + 1] = cntA[i] + (cs[i] == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (cs[i] == 'B' ? 1 : 0);
        }
        long ans = solve(0, 0, r + c, r + c);
        System.out.println(ans);
    }

    public static void main(String[] args) {
        new Test().start();
    }
}
